fn parse_table_header(sv : StringView) -> Array[String] raise TomlError {
  let sv = sv.trim()
  guard sv.length() >= 2 && sv[sv.length() - 1] == b']' else {
    raise TomlError("invalid table header: \{sv}")
  }
  let inner = sv.sub(start=1, end=sv.length() - 1).trim()
  if inner.is_empty() {
    raise TomlError("empty table header: \{sv}")
  }
