    Some((raw_key, rest)) => {
      let key = parse_dotted_key(raw_key.trim())?
      (key, rest.trim())
    }
  }
}

///|
/// Parse a dotted key like `a` or `a.b.c`.
fn parse_dotted_key(sv : StringView) -> Array[String] raise TomlError {
  let parts = sv.split(".")
  let mut keys : Array[String] = []
  for part in parts {
    let p = part.trim()
    if p.is_empty() {
