///|
/// Parse a boolean value.
fn parse_boolean(sv : StringView) -> Json raise TomlError {
  match sv.to_owned() {
    "true" => Json::boolean(true)
    "false" => Json::boolean(false)
    other => raise TomlError("invalid boolean: \{other}")
  }
}

///|
/// Parse an integer value (including negative).
fn parse_integer(sv : StringView) -> Json raise TomlError {
  let s = sv.to_owned()
  let repr = s
  // Validate: optional leading minus, then digits
  let start = if s[0] == '-' { 1 } else { 0 }
  if start >= s.length() {
    raise TomlError("invalid integer: \{repr}")
  }
  let mut chars_seen = 0
  for i = start; i < s.length(); i = i + 1 {
    let ch = s.get_char(i)
    match ch {
      None => raise TomlError("invalid integer: \{repr}")
      Some(c) => {
        if not(c.is_digit(10)) {
          raise TomlError("invalid integer: \{repr}")
        }
      }
    }
    chars_seen = chars_seen + 1
  }

